/*
 * Generated by Claude Fable 5.2 High operated by tfenby@knightwatch.net on 2026-11-18
 * Reviewed by [your name here] on [date of review]
 * Thoroughness of review: [0-100%]
 *
 * Simulates D0/D1 edges on a PC and checks what wiegand_capture.c records.
 * This tests the capture LOGIC only. It says nothing about real pin
 * electrical behaviour or interrupt latency on a Flipper.
 */
#include "../wiegand.h"

/* ---- stand-ins ----------------------------------------------------------- */
FakeDwt fake_dwt = {0};
GpioPin gpio_ext_pa4 = {true, NULL, GpioModeAnalog};
GpioPin gpio_ext_pa7 = {true, NULL, GpioModeAnalog};
static int events_sent = 0;
static uint32_t last_event = 0;

bool furi_hal_gpio_read(const GpioPin* pin) {
    return pin->level;
}
void furi_hal_gpio_init_simple(const GpioPin* pin, GpioMode mode) {
    ((GpioPin*)pin)->mode = mode;
}
void furi_hal_gpio_add_int_callback(const GpioPin* pin, GpioExtiCallback cb, void* ctx) {
    UNUSED(ctx);
    if(pin->callback != NULL) {
        printf("FAIL: interrupt callback added twice\n");
    }
    ((GpioPin*)pin)->callback = cb;
}
void furi_hal_gpio_remove_int_callback(const GpioPin* pin) {
    ((GpioPin*)pin)->callback = NULL;
}
uint32_t furi_ms_to_ticks(uint32_t ms) {
    return ms;
}
int furi_timer_start(FuriTimer* timer, uint32_t ticks) {
    UNUSED(timer);
    UNUSED(ticks);
    return 0;
}
int furi_timer_stop(FuriTimer* timer) {
    UNUSED(timer);
    return 0;
}
void view_dispatcher_send_custom_event(ViewDispatcher* dispatcher, uint32_t event) {
    UNUSED(dispatcher);
    events_sent++;
    last_event = event;
}

/* ---- simulation helpers -------------------------------------------------- */
static int failures = 0;
static int checks = 0;
#define CHECK(cond)                                              \
    do {                                                         \
        checks++;                                                \
        if(!(cond)) {                                            \
            failures++;                                          \
            printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        }                                                        \
    } while(0)

static void advance_us(uint32_t us) {
    fake_dwt.CYCCNT += us * WIEGAND_TICKS_PER_US;
}

static void edge(GpioPin* pin, bool level) {
    pin->level = level;
    if(pin->callback && pin->mode == GpioModeInterruptRiseFall) pin->callback(NULL);
}

static GpioPin* line(char bit) {
    return bit == '1' ? &gpio_ext_pa7 : &gpio_ext_pa4;
}

/* One frame: each bit is a low pulse of `width` us, bits `period` us apart. */
static void send_frame(const char* bits, uint32_t width, uint32_t period) {
    for(size_t i = 0; bits[i]; i++) {
        edge(line(bits[i]), false);
        advance_us(width);
        edge(line(bits[i]), true);
        advance_us(period - width);
    }
}

static bool captured_equals(const char* bits) {
    if(bit_count != (int)strlen(bits)) return false;
    for(int i = 0; i < bit_count; i++) {
        if(data[i] != (bits[i] == '1')) return false;
    }
    return true;
}

static void make_bits(char* out, int n, unsigned seed) {
    for(int i = 0; i < n; i++) {
        seed = seed * 1103515245u + 12345u;
        out[i] = ((seed >> 16) & 1) ? '1' : '0';
    }
    out[n] = '\0';
}

/* Send one frame of n bits and confirm it is captured whole. */
static void check_length(int n) {
    char bits[300];
    make_bits(bits, n, (unsigned)n * 7919u);
    wiegand_capture_start();
    send_frame(bits, 40, 2000);
    CHECK(!wiegand_capture_has_frame());
    advance_us(30000);
    CHECK(wiegand_capture_poll());
    CHECK(wiegand_capture_has_frame());
    CHECK(captured_equals(bits));
    CHECK(overflow_bits == 0);
    CHECK(glitch_count == 0);
    wiegand_capture_stop();
}

int main(void) {
    WiegandTiming timing;

    /* 1. Every length from 1 to MAX_BITS is captured, including the ones the
     *    original app threw away (25, 27, 33...) and the long ones (56, 64). */
    for(int n = 1; n <= MAX_BITS; n++) check_length(n);

    /* 2. Timing of a standard frame: 40 us pulses, 2 ms apart. */
    wiegand_capture_start();
    send_frame("10110011100011110000111110", 40, 2000);
    advance_us(30000);
    CHECK(wiegand_capture_poll());
    CHECK(bit_count == 26);
    wiegand_capture_timing(&timing);
    CHECK(timing.pulse_min == 40 && timing.pulse_avg == 40 && timing.pulse_max == 40);
    CHECK(timing.has_period);
    CHECK(timing.period_min == 2000 && timing.period_avg == 2000 && timing.period_max == 2000);
    wiegand_capture_stop();

    /* 3. No frame is reported while bits are still arriving, or before any. */
    wiegand_capture_start();
    advance_us(500000);
    CHECK(!wiegand_capture_poll());
    send_frame("1010", 40, 2000);
    CHECK(!wiegand_capture_poll());
    advance_us(20000); /* 22 ms since the last edge: still inside the gap */
    CHECK(!wiegand_capture_poll());
    advance_us(10000);
    CHECK(wiegand_capture_poll());
    CHECK(!wiegand_capture_poll()); /* reported once only */

    /* 4. After a frame is reported, later edges do not alter it. */
    send_frame("1111", 40, 2000);
    CHECK(captured_equals("1010"));
    wiegand_capture_stop();

    /* 5. Longer than the buffer: kept bits are intact and the rest counted. */
    {
        char bits[300];
        make_bits(bits, MAX_BITS + 5, 42);
        wiegand_capture_start();
        send_frame(bits, 40, 2000);
        advance_us(30000);
        CHECK(wiegand_capture_poll());
        CHECK(bit_count == MAX_BITS);
        CHECK(overflow_bits == 5);
        bits[MAX_BITS] = '\0';
        CHECK(captured_equals(bits));
        wiegand_capture_stop();
    }

    /* 6. A spike too short to see low (rise with no fall) is a glitch, not a
     *    bit. */
    wiegand_capture_start();
    send_frame("101", 40, 2000);
    gpio_ext_pa4.level = true;
    gpio_ext_pa4.callback(NULL);
    send_frame("01", 40, 2000);
    advance_us(30000);
    CHECK(wiegand_capture_poll());
    CHECK(captured_equals("10101"));
    CHECK(glitch_count == 1);
    wiegand_capture_stop();

    /* 7. A line already low when capture starts: its release is not a bit. */
    gpio_ext_pa7.level = false;
    wiegand_capture_start();
    advance_us(100000);
    edge(&gpio_ext_pa7, true);
    advance_us(30000);
    CHECK(!wiegand_capture_poll());
    CHECK(bit_count == 0);
    CHECK(glitch_count == 1);
    wiegand_capture_stop();

    /* 8. Slow edges show up as a longer pulse (the cable-test measurement),
     *    and jitter shows in min/max. */
    wiegand_capture_start();
    edge(&gpio_ext_pa4, false);
    advance_us(40);
    edge(&gpio_ext_pa4, true);
    advance_us(1960);
    edge(&gpio_ext_pa7, false);
    advance_us(70);
    edge(&gpio_ext_pa7, true);
    advance_us(2130);
    edge(&gpio_ext_pa4, false);
    advance_us(55);
    edge(&gpio_ext_pa4, true);
    advance_us(30000);
    CHECK(wiegand_capture_poll());
    wiegand_capture_timing(&timing);
    CHECK(timing.pulse_min == 40 && timing.pulse_max == 70 && timing.pulse_avg == 55);
    CHECK(timing.period_min == 2000 && timing.period_max == 2200 && timing.period_avg == 2100);
    wiegand_capture_stop();

    /* 9. The cycle counter wrapping mid-frame does not disturb anything. */
    fake_dwt.CYCCNT = UINT32_MAX - (10000u * WIEGAND_TICKS_PER_US);
    wiegand_capture_start();
    send_frame("1100101011110000110010101111000011", 40, 2000);
    advance_us(30000);
    CHECK(wiegand_capture_poll());
    CHECK(captured_equals("1100101011110000110010101111000011"));
    wiegand_capture_timing(&timing);
    CHECK(timing.pulse_min == 40 && timing.pulse_max == 40);
    CHECK(timing.period_min == 2000 && timing.period_max == 2000);
    wiegand_capture_stop();

    /* 10. Single-bit frame (noise that looks like one pulse) has no period. */
    wiegand_capture_start();
    send_frame("0", 40, 2000);
    advance_us(30000);
    CHECK(wiegand_capture_poll());
    wiegand_capture_timing(&timing);
    CHECK(bit_count == 1 && !timing.has_period && timing.pulse_avg == 40);
    wiegand_capture_stop();

    /* 11. Pins are parked as plain inputs when not capturing, never analog,
     *     until the app hands them back on exit. */
    CHECK(gpio_ext_pa4.mode == GpioModeInput && gpio_ext_pa7.mode == GpioModeInput);
    CHECK(gpio_ext_pa4.callback == NULL && gpio_ext_pa7.callback == NULL);
    wiegand_capture_release_pins();
    CHECK(gpio_ext_pa4.mode == GpioModeAnalog && gpio_ext_pa7.mode == GpioModeAnalog);

    /* 12. The poll timer posts exactly one frame event per frame, and a level
     *     event only when the idle levels change. */
    {
        App app;
        memset(&app, 0, sizeof(app));
        events_sent = 0;
        wiegand_scene_capture_start(&app);
        CHECK(app.levels == 3);
        for(int i = 0; i < 20; i++) wiegand_timer_callback(&app);
        CHECK(events_sent == 0);
        gpio_ext_pa4.level = false; /* D0 held low: stuck line */
        for(int i = 0; i < 5; i++) wiegand_timer_callback(&app);
        CHECK(events_sent == 1 && last_event == WiegandCaptureLevelEvent);
        CHECK(app.levels == 2);
        gpio_ext_pa4.level = true;
        for(int i = 0; i < 5; i++) wiegand_timer_callback(&app);
        CHECK(events_sent == 2 && app.levels == 3);
        send_frame("1001", 40, 2000);
        advance_us(30000);
        wiegand_timer_callback(&app);
        CHECK(events_sent == 3 && last_event == WiegandCaptureFrameEvent);
        for(int i = 0; i < 20; i++) wiegand_timer_callback(&app);
        CHECK(events_sent == 3);
        wiegand_scene_capture_stop(&app);
    }

    printf("capture simulation: %d checks, %d failures\n", checks, failures);
    return failures == 0 ? 0 : 1;
}
